/*
 * Multi-line comment.
 * Every C program starts at main().
 */
#include <stdio.h>      /* preprocessor include */

int main(void) {        /* no arguments, integer return type */
    int total = 0;      /* declaration: type, name, initializer */
    total = 4 + 6;      /* expression statement, ends with a semicolon */

    {
        int scoped = 99;    /* visible only inside this block */
        total += scoped;
    }

    printf("total = %d\n", total);  /* total = 109 */
    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <inttypes.h>

int main(void) {
    char letter = 'A';                /* 1 byte */
    short small = 32000;              /* typically 2 bytes */
    int count = 42;                   /* typically 4 bytes */
    long large = 900000L;             /* 4 bytes on Windows, 8 on 64-bit Linux */
    long long huge = 9000000000LL;    /* at least 8 bytes */
    unsigned int mask = 0xFFFFu;      /* non-negative values only */
    float ratio = 0.75f;              /* single precision */
    double precise = 3.141592653589793;
    bool ready = true;                /* needs <stdbool.h> */
    int32_t fixed32 = -2000000000;    /* exact 32-bit width */
    uint8_t byte = 255;               /* exact 8-bit width */

    printf("%c %d %d %ld %lld\n", letter, small, count, large, huge);
    printf("%u %.2f %.3f %d\n", mask, ratio, precise, ready);
    printf("%" PRId32 " %u\n", fixed32, (unsigned)byte);
    return 0;
}

