#include <stdio.h>

int counter = 0;              /* file scope, zero-initialized */

int main(void) {
    int apples = 12;          /* automatic storage, lives until the block ends */
    const double tax = 0.23;  /* read-only after initialization */
    static int calls;         /* persists across calls, starts at zero */

    calls++;
    apples += 3;
    counter = apples * 2;

    printf("%d apples, %d calls, %.2f tax\n", apples, calls, tax);
    printf("counter = %d\n", counter);
    return 0;
}

#include <stdio.h>

int main(void) {
    int a = 17;
    int b = 5;

    printf("%d %d %d %d %d\n", a + b, a - b, a * b, a / b, a % b); /* 22 12 85 3 2 */
    printf("%d %d %d\n", a > b, a == b, a != b);                    /* 1 0 1 */
    printf("%d %d %d\n", a & b, a | b, a ^ b);                      /* 1 21 20 */
    printf("%d %d\n", a << 1, a >> 1);                              /* 34 8 */

    int ok = (a > 10 && b < 10) ? 1 : 0;  /* logical AND plus ternary */
    a += 3;                               /* compound assignment: a becomes 20 */
    printf("%d %d\n", ok, a);             /* 1 20 */

    int value = 2 + 3 * 4;                /* 14, multiplication first */
    int forced = (2 + 3) * 4;             /* 20, parentheses win */
    printf("%d %d\n", value, forced);
    return 0;
}

#include <stdio.h>

int main(void) {
    int score = 78;

    if (score >= 90) {
        puts("A");
    } else if (score >= 70) {
        puts("B");
    } else {
        puts("C");
    }

    switch (score / 10) {
        case 9:
            puts("excellent");
            break;
        case 7:
            puts("good");
            break;
        default:
            puts("keep going");
            break;
    }

    for (int i = 0; i < 3; i++) {
        printf("for %d\n", i);
    }

    int n = 3;
    while (n > 0) {
        printf("while %d\n", n);
        n--;
    }

    do {
        puts("runs at least once");
    } while (n > 0);

    return 0;
}

