    FILE *fp = fopen("data.txt", "r");
    if (fp == NULL) {
        goto cleanup;          /* single exit point for cleanup */
    }
    /* ... read from fp ... */
cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    return 0;
}

#include <stdio.h>

int add(int a, int b);          /* prototype: lets main call add before its definition */
void swap(int *a, int *b);

int main(void) {
    printf("%d\n", add(4, 9));  /* 13 */

    int x = 1;
    int y = 2;
    swap(&x, &y);                /* pass addresses to let the function modify them */
    printf("%d %d\n", x, y);     /* 2 1 */
    return 0;
}

int add(int a, int b) {
    return a + b;                /* arguments arrive as copies */
}

void swap(int *a, int *b) {
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

#include <stdio.h>

unsigned long factorial(unsigned int n) {
    if (n <= 1) {
        return 1UL;              /* base case */
    }
    return n * factorial(n - 1);
}

int main(void) {
    for (unsigned int i = 0; i < 6; i++) {
        printf("%u! = %lu\n", i, factorial(i));
    }
    return 0;
}

