#include <stdio.h>

int sum(const int values[], size_t count) {
    int total = 0;
    for (size_t i = 0; i < count; i++) {
        total += values[i];
    }
    return total;
}

int main(void) {
    int data[4] = {5, 10, 15, 20};

    /* The array decays to a pointer, so the length must be passed separately. */
    printf("%d\n", sum(data, 4));   /* 50 */
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void) {
    char name[] = "Ada";              /* mutable array, 4 bytes including '\0' */
    char greeting[32];

    printf("%zu\n", strlen(name));    /* 3, the terminator is not counted */

    strcpy(greeting, "Hello, ");
    strcat(greeting, name);
    printf("%s\n", greeting);         /* Hello, Ada */

    if (strcmp(name, "Ada") == 0) {   /* compare contents, never with == */
        puts("names match");
    }

    char label[16];
    int written = snprintf(label, sizeof label, "%s-%d", name, 42);
    printf("%s (%d chars)\n", label, written);  /* Ada-42 (6 chars) */
    return 0;
}

