#include <stdio.h>

int main(void) {
    int value = 42;
    int *ptr = &value;              /* pointer holds the address of value */

    printf("%d\n", *ptr);           /* 42: dereference reads the target */
    *ptr = 7;                       /* write through the pointer */
    printf("%d\n", value);          /* 7 */

    int data[3] = {10, 20, 30};
    int *walk = data;               /* array name decays to &data[0] */
    printf("%d %d\n", *walk, *(walk + 2));  /* 10 30 */

    int *missing = NULL;            /* explicit "points nowhere" value */
    if (missing == NULL) {
        puts("not pointing anywhere");
    }
    return 0;
}

#include <stdio.h>

void increment(int *value) {
    (*value)++;                     /* parentheses: increment the target, not the pointer */
}

int main(void) {
    int x = 5;
    int *const fixed = &x;          /* the pointer itself cannot move */
    const int *readonly = &x;       /* the target cannot be changed through this pointer */

    increment(fixed);
    printf("%d\n", *readonly);      /* 6 */
    return 0;
}

#include <stdio.h>

typedef struct {
    char name[32];
    int year;
    double rating;
} Book;

typedef union {
    float as_float;
    unsigned int as_bits;
} FloatBits;

int main(void) {
    Book book = {
        .name = "The C Programming Language",
        .year = 1978,
        .rating = 4.7,
    };
    Book copy = book;               /* the whole struct is copied by value */

    printf("%s (%d) %.1f\n", copy.name, copy.year, copy.rating);

    FloatBits bits;
    bits.as_float = 1.5f;           /* both members share the same storage */
    printf("0x%08X\n", bits.as_bits);  /* 0x3FC00000 on IEEE-754 platforms */
    return 0;
}

#include <stdio.h>

typedef struct Node {
    int value;
    struct Node *next;              /* a struct may point to its own type */
} Node;

int main(void) {
    Node tail = {.value = 3, .next = NULL};
    Node head = {.value = 1, .next = &tail};

    for (Node *cur = &head; cur != NULL; cur = cur->next) {
        printf("%d ", cur->value);  /* 1 3 */
    }
    putchar('\n');
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t n = 4;
    int *values = malloc(n * sizeof *values);
    if (values == NULL) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }

    for (size_t i = 0; i < n; i++) {
        values[i] = (int)(i * i);
    }
    printf("%d\n", values[3]);      /* 9 */

    int *bigger = realloc(values, 8 * sizeof *values);
    if (bigger == NULL) {
        free(values);               /* the original block is still valid */
        return 1;
    }
    values = bigger;                /* never assign realloc straight back */

    values[7] = 49;
    printf("%d\n", values[7]);     /* 49 */

    free(values);                   /* release exactly once */
    values = NULL;                  /* avoid accidental reuse */
    return 0;
}

