#include <stdio.h>
#include <stdlib.h>

int main(void) {
    /* 1. Dereferencing NULL: segmentation fault */
    int *null_ptr = NULL;
    if (null_ptr != NULL) {
        *null_ptr = 10;
    }

    /* 2. Off-by-one: valid indexes for values[3] are 0, 1, and 2 */
    int values[3] = {1, 2, 3};
    values[2] = 30;

    /* 3. scanf needs the address of the variable */
    int age = 0;
    if (scanf("%d", &age) != 1) {
        age = 0;
    }

    /* 4. Bound the copy: snprintf always leaves room for the terminator */
    char name[8];
    snprintf(name, sizeof name, "%s", "Ada");

    /* 5. Every malloc needs one matching free */
    int *heap = malloc(4 * sizeof *heap);
    if (heap != NULL) {
        heap[0] = age;
        free(heap);
    }

    printf("%d %s\n", values[2], name);
    return 0;
}
